### trier_tableau
```javascript
function trier_tableau(arr) {
  // QuickSort implementation without using Array.prototype.sort()
  if (!Array.isArray || !arr.length) return arr.slice();

  function quicksort(a, left, right) {
    if (left >= right) return;
    const pivot = a[Math.floor((left + right) / 2)];
    let i = left, j = right;
    while (i <= j) {
      while (a[i] < pivot) i++;
      while (a[j] > pivot) j--;
      if (i <= j) {
        [a[i], a[j]] = [a[j], a[i]];
        i++; j--;
      }
    }
    quicksort(a, left, j);
    quicksort(a, i, right);
  }

  const result = arr.slice();
  quicksort(result, 0, result.length - 1);
  return result;
}
```

